// Generates src/scrcpy-server.ts from the vendored scrcpy server jar (base64).
const fs = require("fs")
const path = require("path")

const binPath = path.join(__dirname, "..", "vendor", "scrcpy-server-v3.3.3.bin")
const outPath = path.join(__dirname, "..", "src", "scrcpy-server.ts")

const bytes = fs.readFileSync(binPath)
const b64 = bytes.toString("base64")
const header =
  "// AUTO-GENERATED by script/gen-server-module.cjs — do not edit.\n" +
  "// Source: vendor/scrcpy-server-v3.3.3.bin (Apache-2.0, Genymobile scrcpy v3.3.3).\n" +
  "// Base64 keeps the single-CJS GUI bundle free of emitted asset files.\n\n"
const body = `export const SCRCPY_SERVER_BASE64 =\n  "${b64}"\n`
fs.writeFileSync(outPath, header + body)
console.log("wrote", outPath, fs.statSync(outPath).size, "bytes from", bytes.length, "byte jar")
